if(!exists('aggregate_netting_set_exposure'))library(creditratingsystem)
ccr_error<-function(code,expr){e<-tryCatch({force(expr);NULL},error=identity);stopifnot(inherits(e,'creditratingsystem_error'),identical(e$code,code))}
ccr_near<-function(x,y)stopifnot(isTRUE(all.equal(as.numeric(x),as.numeric(y),tolerance=1e-12)))
ccr_dates<-c('2024-01-01','2024-01-02','2024-01-03')
ccr_net<-function(values=c(100,120,150),separate=FALSE){rows<-list();for(i in 1:3)for(t in c('a','b'))rows[[length(rows)+1L]]<-list(path_id='p',date=ccr_dates[i],trade_id=t,currency='EUR',value=if(t=='a')values[i] else -60)
 base<-list(counterparty_id='cp',legally_enforceable=TRUE,evidence_reference='user-evidence',known_at=ccr_dates[1],effective_from=ccr_dates[1],effective_until=NULL)
 agreements<-if(separate)lapply(c('a','b'),function(t)c(base,list(netting_set_id=t,trade_ids=list(t)))) else list(c(base,list(netting_set_id='n',trade_ids=list('a','b'))))
 aggregate_netting_set_exposure(rows,agreements,lapply(ccr_dates,function(d)list(path_id='p',date=d,currency='EUR',rate=1)),ccr_dates[1],'EUR','EX_DIVIDEND_BEFORE_MARGIN')}
ccr_margin<-function(net,lag=FALSE,haircut=0){policy<-list(netting_set_id='n',known_at=ccr_dates[1],collateral_currency='EUR',initial_units=0,threshold_received=0,threshold_posted=0,minimum_transfer_amount=0,ownership='TITLE_TRANSFER',received_enforceable=TRUE,posted_returnability='UNSECURED_CLAIM',posted_claim_netting_enforceable=TRUE,reuse='ALLOWED')
 calls<-lapply(1:3,function(i)list(call_id=as.character(i),path_id='p',netting_set_id='n',valuation_date=ccr_dates[i],call_date=ccr_dates[i],settlement_date=ccr_dates[if(lag)min(i+1,3) else i],dispute_delay_days=0))
 market<-lapply(ccr_dates,function(d)list(path_id='p',date=d,netting_set_id='n',unit_price=1,fx_rate=1,currency='EUR',received_haircut=haircut,posted_haircut=haircut))
 list(netting_paths=net,margin_policies=list(policy),call_calendar=calls,collateral_market_paths=market)}
n<-ccr_net();ccr_near(vapply(n$value$paths,`[[`,numeric(1),'positive_exposure'),c(40,60,90));s<-ccr_net(separate=TRUE);ccr_near(sum(vapply(Filter(function(r)r$date==ccr_dates[1],s$value$paths),`[[`,numeric(1),'positive_exposure')),100)
a<-ccr_margin(n);m<-do.call(simulate_collateral_margin,a);ccr_near(vapply(m$value$paths,`[[`,numeric(1),'closing_units'),c(40,60,90));ccr_near(vapply(m$value$paths,`[[`,numeric(1),'residual_exposure'),rep(0,3))
m<-do.call(simulate_collateral_margin,ccr_margin(n,TRUE));ccr_near(vapply(m$value$paths,`[[`,numeric(1),'residual_exposure'),c(40,20,0))
a<-ccr_margin(ccr_net(rep(100,3)));for(i in 1:3)a$call_calendar[[i]]$settlement_date<-ccr_dates[3];m<-do.call(simulate_collateral_margin,a);ccr_near(vapply(m$value$call_ledger,`[[`,numeric(1),'transfer_units'),c(40,0,0))
a<-ccr_margin(ccr_net(rep(-40,3)),haircut=.2);m<-do.call(simulate_collateral_margin,a);ccr_near(m$value$paths[[1]]$closing_units,-125);ccr_near(m$value$paths[[1]]$residual_exposure,25);a$margin_policies[[1]]$posted_claim_netting_enforceable<-FALSE;m<-do.call(simulate_collateral_margin,a);ccr_near(m$value$paths[[1]]$residual_exposure,125);a$margin_policies[[1]]$ownership<-'SECURITY_INTEREST';a$margin_policies[[1]]$posted_returnability<-'BANKRUPTCY_REMOTE';m<-do.call(simulate_collateral_margin,a);ccr_near(m$value$paths[[1]]$residual_exposure,0)
a<-ccr_margin(n);a$call_calendar<-a$call_calendar[1];a$call_calendar[[1]]$dispute_delay_days<-1;m<-do.call(simulate_collateral_margin,a);ccr_near(vapply(m$value$paths,`[[`,numeric(1),'residual_exposure'),c(40,20,50))
a<-ccr_margin(n);a$call_calendar[[1]]$valuation_date<-ccr_dates[2];ccr_error('COLLATERAL_DATE',do.call(simulate_collateral_margin,a))
a<-ccr_margin(n);a$collateral_market_paths[[3]]$unit_price<-.5;m<-do.call(simulate_collateral_margin,a);events<-list(list(path_id='p',netting_set_id='n',margin_observation_date=ccr_dates[1],default_date=ccr_dates[1],closeout_date=ccr_dates[3]));flows<-list(list(cashflow_id='unpaid',path_id='p',netting_set_id='n',date=ccr_dates[2],amount=10,currency='EUR',included_in_closeout_value=FALSE))
co<-closeout_exposure_at_default(n,m,events,flows,'AFTER_DATE_EVENTS','UNSETTLED_EXCLUDED_FROM_CLOSEOUT_VALUE')$value$closeouts[[1]];ccr_near(co$frozen_collateral_units,40);ccr_near(co$recognized_received,20);ccr_near(co$closeout_exposure,80)
co<-closeout_exposure_at_default(n,m,events,flows,'BEFORE_DATE_EVENTS','UNSETTLED_EXCLUDED_FROM_CLOSEOUT_VALUE')$value$closeouts[[1]];ccr_near(co$closeout_exposure,100)
flows[[1]]$included_in_closeout_value<-TRUE;ccr_error('CLOSEOUT_CASHFLOW',closeout_exposure_at_default(n,m,events,flows,'AFTER_DATE_EVENTS','UNSETTLED_EXCLUDED_FROM_CLOSEOUT_VALUE'))
events[[1]]$closeout_date<-'2024-01-04';ccr_error('INSUFFICIENT_PATH_EXTENSION',closeout_exposure_at_default(n,m,events,list(),'AFTER_DATE_EVENTS','UNSETTLED_EXCLUDED_FROM_CLOSEOUT_VALUE'))
cat('Native collateral/netting/closeout independent cases PASS\n')
